// Applied rules: [C3]
// Skipped rules: [III④: Only concrete hit is [9], a single terminal write through `transTo.offset(nbTransTo)`. No L1-L4 length source is available for a sound slice view over `transTo` at that point, and the view would serve essentially one access, violating the rule's own abstain guidance. Also this site is better handled indirectly by C3 hoisting of `transTo`/`nbTransTo` locals.]
fn xmlRegStateAddTransTo(
    mut ctxt: xmlRegParserCtxtPtr,
    mut target: xmlRegStatePtr,
    mut from: c_int,
) {
    unsafe {
        // SAFETY: `target` is assumed valid by the original function contract; we only
        // cache and update its fields locally within this function, preserving the same
        // raw-pointer semantics and failure behavior as the original code.
        let mut max_trans_to = (*target).maxTransTo;
        if max_trans_to == 0 as c_int {
            max_trans_to = 8 as c_int;
            (*target).maxTransTo = max_trans_to;
            let trans_to = xmlMalloc.expect("non-null function pointer")(
                (max_trans_to as size_t)
                    .wrapping_mul(::core::mem::size_of::<c_int>() as size_t),
            ) as *mut c_int;
            (*target).transTo = trans_to;
            if trans_to.is_null() {
                xmlRegexpErrMemory(
                    ctxt,
                    b"adding transition\0" as *const u8 as *const c_char,
                );
                (*target).maxTransTo = 0 as c_int;
                return;
            }
        } else {
            let nb_trans_to = (*target).nbTransTo;
            if nb_trans_to >= max_trans_to {
                let trans_to = (*target).transTo;
                max_trans_to *= 2 as c_int;
                (*target).maxTransTo = max_trans_to;
                let tmp = xmlRealloc.expect("non-null function pointer")(
                    trans_to as *mut c_void,
                    (max_trans_to as size_t)
                        .wrapping_mul(::core::mem::size_of::<c_int>() as size_t),
                ) as *mut c_int;
                if tmp.is_null() {
                    xmlRegexpErrMemory(
                        ctxt,
                        b"adding transition\0" as *const u8 as *const c_char,
                    );
                    (*target).maxTransTo /= 2 as c_int;
                    return;
                }
                (*target).transTo = tmp;
            }
        }

        let nb_trans_to = (*target).nbTransTo;
        let trans_to = (*target).transTo;
        *trans_to.offset(nb_trans_to as isize) = from;
        (*target).nbTransTo = nb_trans_to + 1;
    }
}

